namespace target=shared_target;namespace sd=shared_duffy;
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);int result=2;try{need(argc==11,"same frozen inputs and NEW diagnostic output");auto p=curved::read(argv[1]);const auto f=load_saved(std::string(argv[2])+"/shared_state.bin",p);const sf::FrozenThermal heat(f,p.parameters[2],p.parameters[1],1);auto context=target::retained_context(argv[5],f,heat);auto sources=target::retained_sources(argv[5],argv[6],f);target::coverage_overlay(argv[7],sources);std::string dest=argv[10];FILE*out=fopen((dest+"/DIAGNOSTIC_reference80_queries_rank"+std::to_string(rank)+".bin").c_str(),"wb");need(out,"reference80 diagnostic file");uint64_t points=0,sources_checked=0,sum_checks=0;for(int s=rank;s<384;s+=ranks)if(sources[s].classification==2&&!sources[s].empty){auto m=sd::compile(f,s);auto charts=sd::charts(m);target::Reference80Accumulator diagnostic;S oracle_sum[12];for(int ci=0;ci<6;ci++){auto q=sd::evaluate(m,charts[ci],S(Q(.5L)),S(Q(.5L)));target::point_reference80(p,m,q,q.reference_jacobian/S(100),context[f.triangle[s].cell],diagnostic,out);auto oracle=target::physical_query(p,q.field,q.X[0],q.X[1],q.reference_jacobian/S(100),context[f.triangle[s].cell]);for(int k=0;k<12;k++)oracle_sum[k]=oracle_sum[k]+oracle[k];}target::finish_reference80(diagnostic);for(int k=0;k<12;k++){need(fabsq(diagnostic.moment[k].n-oracle_sum[k].n)<=sf::add(diagnostic.moment[k].e,oracle_sum[k].e),"binary80 pairwise source sum encloses Q128 oracle sum");sum_checks++;}points+=diagnostic.points;sources_checked++;}fclose(out);uint64_t total=0,source_total=0,total_sums=0;MPI_Reduce(&points,&total,1,MPI_UINT64_T,MPI_SUM,0,MPI_COMM_WORLD);MPI_Reduce(&sources_checked,&source_total,1,MPI_UINT64_T,MPI_SUM,0,MPI_COMM_WORLD);MPI_Reduce(&sum_checks,&total_sums,1,MPI_UINT64_T,MPI_SUM,0,MPI_COMM_WORLD);if(rank==0){need(source_total==26&&total==156,"six diagnostic points on each actual clipped source");checkpoint(dest+"/caller_unchanged_state.bin",f,1);checkpoint(dest+"/immutable_heat_generating_state.bin",heat.generating,1);printf("{\"scope\":\"DIAGNOSTIC CPU binary80 graph and all12 binding; no clipped target quadrature or publication\",\"sources\":%llu,\"points\":%llu,\"field_comparisons\":%llu,\"all12_comparisons\":%llu,\"pairwise_source_sum_checks\":%llu,\"LDBL_MANT_DIG\":%d,\"record_bytes\":%zu,\"binary64_input_and_cache_uncertainty_retained\":true,\"CUDA_double_backend_certified\":false}\n",(unsigned long long)source_total,(unsigned long long)total,(unsigned long long)(17*total),(unsigned long long)(12*total),(unsigned long long)total_sums,LDBL_MANT_DIG,sizeof(target::Reference80Positive));}result=0;}catch(const std::exception&e){fprintf(stderr,"rank%d FAIL %s\n",rank,e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return result;}
